    import time

    LANGUAGE_WRAPPER = 'Consider all {n}×{n} arrays with entries in {−1,1}. Let r = {row_sums} and s = {col_sums}. How many such arrays are there in which the i-th row sum equals r_i for each i and the j-th column sum equals s_j for each j?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate a random even n in {4,6} with bias toward 6 for hardness
while True:
    n = rng.choice([4, 6, 6, 6])
    # Choose allowed counts of +1 per row to avoid trivial extremes
    if n == 4:
        allowed = [1, 2, 3]
    else:
        allowed = [2, 3, 4]
    row_ones = [rng.choice(allowed) for _ in range(n)]
    # Ensure at least two distinct row requirements (non-trivial)
    if len(set(row_ones)) < 2:
        continue
    # Build a random 0-1 matrix achieving these row sums
    col_ones = [0] * n
    for i in range(n):
        k = row_ones[i]
        cols = list(range(n))
        rng.shuffle(cols)
        chosen = cols[:k]
        for j in chosen:
            col_ones[j] += 1
    # Ensure columns are not all identical in sum
    if len(set(col_ones)) < 2:
        continue
    # Convert to ±1 margin descriptions
    row_sums = [2 * x - n for x in row_ones]
    col_sums = [2 * x - n for x in col_ones]
    # Basic sanity: avoid the seed's fully symmetric case
    if all(v == 0 for v in row_sums) and all(v == 0 for v in col_sums) and n == 4:
        continue
    return {'n': n, 'row_sums': row_sums, 'col_sums': col_sums}

    def verifier(assign):
# Validate and count number of ±1 matrices with given row/column sums via DP
try:
