    return (False, None)
if not (len(row_sums) == n and len(col_sums) == n):
    return (False, None)
# Parity checks and conversion to 0-1 margins
row_ones = []
col_ones = []
for r in row_sums:
    if not isinstance(r, int):
        return (False, None)
    if (n + r) % 2 != 0:
        # parity mismatch
        return (False, None)
    k = (n + r) // 2
    if k < 0 or k > n:
        return (False, None)
    row_ones.append(k)
for c in col_sums:
    if not isinstance(c, int):
        return (False, None)
    if (n + c) % 2 != 0:
        return (False, None)
    k = (n + c) // 2
    if k < 0 or k > n:
        return (False, None)
    col_ones.append(k)
if sum(row_ones) != sum(col_ones):
    # Total +1 counts must match
    return (False, None)
# Extra difficulty constraints: avoid trivial symmetric instances
if len(set(row_sums)) < 2 or len(set(col_sums)) < 2:
    return (False, None)
# Count number of 0-1 matrices with margins row_ones, col_ones via DP over rows
from functools import lru_cache

# Quick feasibility pruning: if any column requirement exceeds number of rows, impossible
if any(x > n for x in col_ones):
    return (False, None)
# Another feasibility check: Gale-Ryser/Fulkerson is overkill; DP will handle infeasibility anyway.

# Precompute, for speed, for each row i the list of all column index subsets of size row_ones[i], but filtered by remaining capacities within recursion.
# We'll generate subsets on the fly given the set of columns with rem>0.
def gen_combos(avail_indices, k):
    # yield tuples of k indices from avail_indices
    res = []
    def backtrack(start, k, path):
        if k == 0:
            res.append(tuple(path))
            return
        # Prune if not enough elements remain
        if start + k > len(avail_indices):
            return
        # Choose avail_indices[start]
        path.append(avail_indices[start])
        backtrack(start + 1, k - 1, path)
        path.pop()
        # Skip it
        backtrack(start + 1, k, path)
    if k < 0 or k > len(avail_indices):
        return []
    backtrack(0, k, [])
    return res

@lru_cache(maxsize=None)
def dp(i, rem):
    # i: current row index; rem: tuple of remaining ones needed in each column
    if i == n:
        # all rows filled; success if all columns satisfied
        return 1 if all(v == 0 for v in rem) else 0
    need = row_ones[i]
    # Count how many columns still available
    avail = [idx for idx, v in enumerate(rem) if v > 0]
    if need < 0 or need > len(avail):
        return 0
    total = 0
    # Enumerate subsets of available columns of size need
    for comb in gen_combos(avail, need):
        rem_list = list(rem)
        feasible = True
        for j in comb:
            v = rem_list[j]
            if v <= 0:
                feasible = False
                break
            rem_list[j] = v - 1
        if not feasible:
            continue
        total += dp(i + 1, tuple(rem_list))
    return total

answer = dp(0, tuple(col_ones))
# Enforce non-triviality of the counting task by requiring a moderately sized solution set
if answer is None or not isinstance(answer, int):
    return (False, None)
if answer <= 5:
    # Too few configurations; likely trivial to brute-force by hand; reject to keep difficulty up
    return (False, None)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

